package main

import (
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"strings"
	"testing"
)

const p15S01ContainerLiteral = "L\uFFFC🙂éשָׁR"

// These expectations describe complete native operations independently of the
// compiler. Carrier identities come from real producers; literal bytes, row
// types, field order and every consumer are authored here, not regenerated by
// the production codec. This is structural evidence, not Apple execution.
func p15S01ContainerRows(rows ...any) map[string]any {
	return map[string]any{"WFSerializationType": "WFDictionaryFieldValue", "Value": map[string]any{"WFDictionaryFieldValueItems": rows}}
}

func p15S01ContainerRow(key any, kind int, value any) map[string]any {
	return map[string]any{"WFKey": key, "WFItemType": kind, "WFValue": value}
}

func p15S01Carrier(g *p15FunctionGraph, literal string) string {
	index := len(g.expected)
	id := g.value("gettext", map[string]any{"WFTextActionText": literal})
	if index < len(g.actual) && p15Param(g.actual[index])["CustomOutputName"] != "Text" {
		g.err = fmt.Errorf("literal carrier lost its canonical Text identity")
	}
	return id
}

func p15S01Dictionary(g *p15FunctionGraph, rows ...any) string {
	return g.value("dictionary", map[string]any{"WFItems": p15S01ContainerRows(rows...)})
}

func p15S01CompleteGraph(g *p15FunctionGraph) error {
	if g.err != nil {
		return g.err
	}
	if len(g.actual) != len(g.expected) {
		return fmt.Errorf("complete graph length %d differs from %d", len(g.actual), len(g.expected))
	}
	positions := map[string]int{}
	for index, action := range g.actual {
		if !reflect.DeepEqual(p15FunctionComparable(action, false), p15FunctionComparable(g.expected[index], false)) {
			return fmt.Errorf("complete action/parameter/edge mismatch at %d: got %#v want %#v", index, p15FunctionComparable(action, false), p15FunctionComparable(g.expected[index], false))
		}
		if id, found := p15Param(action)["UUID"]; found {
			text, ok := id.(string)
			if !ok || text == "" {
				return fmt.Errorf("invalid producer identity at %d", index)
			}
			if _, duplicate := positions[text]; duplicate {
				return fmt.Errorf("duplicate producer identity")
			}
			positions[text] = index
		}
	}
	var visit func(any, int) error
	visit = func(value any, consumer int) error {
		switch item := value.(type) {
		case map[string]any:
			if item["Type"] == "ActionOutput" {
				id, _ := item["OutputUUID"].(string)
				producer, found := positions[id]
				if !found || producer >= consumer {
					return fmt.Errorf("missing or forward producer at %d", consumer)
				}
				if literal, ok := p15Param(g.actual[producer])["WFTextActionText"].(string); ok && strings.ContainsRune(literal, '\uFFFC') && p15Param(g.actual[producer])["CustomOutputName"] == "Text" && item["OutputName"] != "Text" {
					return fmt.Errorf("literal carrier consumer lost the exact output name")
				}
			}
			for _, child := range item {
				if err := visit(child, consumer); err != nil {
					return err
				}
			}
		case []any:
			for _, child := range item {
				if err := visit(child, consumer); err != nil {
					return err
				}
			}
		}
		return nil
	}
	for index, action := range g.actual {
		if err := visit(action, index); err != nil {
			return err
		}
	}
	return nil
}

func p15S01ContainerSource(name string) string {
	literal := fmt.Sprintf("%q", p15S01ContainerLiteral)
	switch name {
	case "map_immutable", "map_mutable":
		declaration := "let"
		if name == "map_mutable" {
			declaration = "var"
		}
		return declaration + " value={\"key\":" + literal + "}\ngetVariable(value)\n"
	case "literal_key_sort":
		return "let value={\"z\uFFFC\":\"last\",\"a\":\"first\"}\ngetVariable(value)\n"
	case "nested_array":
		return "let value={\"nested\":[" + literal + "]}\ngetVariable(value)\n"
	case "list_dictionary":
		return "let value=[{\"key\":" + literal + "}]\ngetVariable(value)\n"
	case "nested_later_call":
		return "let suffix=text(\"SUFFIX\")\nlet seed=text(\"SEED\")\nlet value={\"first\":{\"key\":f\"L\uFFFC{suffix}\"},\"later\":native.action(\"is.workflow.actions.setitemname\",{\"WFName\":\"LATER\"})}\ngetVariable(value)\n"
	case "computed_key_later_call":
		return "let suffix=text(\"SUFFIX\")\nlet seed=text(\"SEED\")\nlet value={f\"K\uFFFC{suffix}\":\"VALUE\",\"later\":native.action(\"is.workflow.actions.setitemname\",{\"WFName\":\"LATER\"})}\ngetVariable(value)\n"
	case "function_scalar":
		return "function accept(value:Text)->Text{return value}\nlet result=accept(" + literal + ")\ngetVariable(result)\n"
	case "optional_scalar_argument":
		return "function echo(value:Text?)->Text?{return value}\ngetVariable(echo(" + literal + "))\n"
	case "optional_map_argument":
		return "function echo(value:Map<Text,AnyContent>?)->Map<Text,AnyContent>?{return value}\ngetVariable(echo({\"key\":" + literal + "}))\n"
	case "optional_scalar_return":
		return "function accept()->Text?{return " + literal + "}\ngetVariable(accept())\n"
	case "optional_map_return":
		return "function accept()->Map<Text,AnyContent>?{return {\"key\":" + literal + "}}\ngetVariable(accept())\n"
	case "function_map_later_argument":
		return "function accept(value:Map<Text,AnyContent>,later:AnyContent)->Text{return \"DONE\"}\nlet seed=text(\"SEED\")\nlet result=accept({\"key\":" + literal + "},later:native.action(\"is.workflow.actions.setitemname\",{\"WFName\":\"LATER\"}))\ngetVariable(result)\n"
	case "registered_map":
		return "let value=getDictionary({\"key\":" + literal + "})\ngetVariable(value)\n"
	case "plain_control":
		return "let value={\"key\":\"ordinary {literal}\"}\ngetVariable(value)\n"
	case "raw_native_control":
		return "native.action(\"is.workflow.actions.dictionary\",native.plist({\"WFItems\":{\"WFSerializationType\":\"WFDictionaryFieldValue\",\"Value\":{\"WFDictionaryFieldValueItems\":[{\"WFItemType\":0,\"WFKey\":\"key\",\"WFValue\":" + literal + "}]}}}))\n"
	}
	panic(name)
}

func p15S01ContainerGraphError(actions []map[string]any, name string) error {
	g := &p15FunctionGraph{actual: actions, groups: map[string]bool{}}
	consume := func(id string) { g.emit("getvariable", map[string]any{"WFVariable": p15FunctionEdge(id)}) }
	key := p15FunctionText("key")
	switch name {
	case "map_immutable", "map_mutable", "nested_array", "list_dictionary", "registered_map":
		literal := p15S01Carrier(g, p15S01ContainerLiteral)
		field := any(p15FunctionText("\uFFFC", literal))
		kind := 0
		if name == "nested_array" {
			key = p15FunctionText("nested")
			kind = 2
			field = map[string]any{"WFSerializationType": "WFArrayParameterState", "Value": []any{map[string]any{"WFItemType": 0, "WFValue": field}}}
		}
		row := p15S01ContainerRow(key, kind, field)
		dictionary := ""
		if name == "registered_map" {
			dictionary = g.value("detect.dictionary", map[string]any{"WFInput": p15S01ContainerRows(row)})
		} else {
			dictionary = p15S01Dictionary(g, row)
		}
		if name == "map_mutable" {
			g.emit("setvariable", map[string]any{"WFVariableName": "value", "WFInput": p15FunctionEdge(dictionary)})
			g.emit("getvariable", map[string]any{"WFVariable": p15FunctionVariable("value")})
		} else if name == "list_dictionary" {
			consume(g.value("list", map[string]any{"WFItems": []any{map[string]any{"WFItemType": 0, "WFValue": p15FunctionEdge(dictionary)}}}))
		} else {
			consume(dictionary)
		}
	case "literal_key_sort":
		keyRef := p15S01Carrier(g, "z\uFFFC")
		consume(p15S01Dictionary(g, p15S01ContainerRow(p15FunctionText("a"), 0, p15FunctionText("first")), p15S01ContainerRow(p15FunctionText("\uFFFC", keyRef), 0, p15FunctionText("last"))))
	case "nested_later_call", "computed_key_later_call":
		suffix := g.value("gettext", map[string]any{"WFTextActionText": "SUFFIX"})
		g.value("gettext", map[string]any{"WFTextActionText": "SEED"})
		later := g.value("setitemname", map[string]any{"WFName": "LATER"})
		prefix := "L\uFFFC"
		if name == "computed_key_later_call" {
			prefix = "K\uFFFC"
		}
		literal := p15S01Carrier(g, prefix)
		template := map[string]any{"WFSerializationType": "WFTextTokenString", "Value": map[string]any{"string": "\uFFFC\uFFFC", "attachmentsByRange": map[string]any{"{0, 1}": map[string]any{"Type": "ActionOutput", "OutputUUID": literal, "OutputName": "Text"}, "{1, 1}": map[string]any{"Type": "ActionOutput", "OutputUUID": suffix, "OutputName": "suffix"}}}}
		first := p15S01ContainerRow(template, 0, p15FunctionText("VALUE"))
		if name == "nested_later_call" {
			first = p15S01ContainerRow(p15FunctionText("first"), 1, p15S01ContainerRows(p15S01ContainerRow(key, 0, template)))
		}
		consume(p15S01Dictionary(g, first, p15S01ContainerRow(p15FunctionText("later"), 0, p15FunctionEdge(later))))
	case "function_scalar":
		envelope := g.header("accept")
		g.output(g.get("arg_0", envelope))
		g.caller()
		literal := p15S01Carrier(g, p15S01ContainerLiteral)
		result := g.call(g.payload("accept", p15FunctionArgument{true, 0, p15FunctionText("\uFFFC", literal)}))
		consume(result)
		g.boundary(g.outer, 2, false)
	case "optional_scalar_argument", "optional_map_argument":
		envelope := g.header("echo")
		value, presence := p15DecodeOptionalArgumentGraph(g, envelope, 0)
		p15ForwardResultGraph(g, value, presence)
		g.caller()
		literal := p15S01Carrier(g, p15S01ContainerLiteral)
		argument := p15FunctionArgument{true, 0, p15FunctionText("\uFFFC", literal)}
		if name == "optional_map_argument" {
			argument = p15FunctionArgument{true, 1, p15S01ContainerRows(p15S01ContainerRow(key, 0, p15FunctionText("\uFFFC", literal)))}
		}
		result, _ := p15ForwardCallGraph(g, "echo", argument, "1", nil, nil)
		consume(result)
		g.boundary(g.outer, 2, false)
	case "optional_scalar_return", "optional_map_return":
		g.header("accept")
		literal := p15S01Carrier(g, p15S01ContainerLiteral)
		argument := p15FunctionArgument{true, 0, p15FunctionText("\uFFFC", literal)}
		if name == "optional_map_return" {
			dictionary := p15S01Dictionary(g, p15S01ContainerRow(key, 0, p15FunctionText("\uFFFC", literal)))
			argument = p15FunctionArgument{true, 0, p15FunctionEdge(dictionary)}
		}
		g.output(p15OptionalCarrierGraph(g, "has_value", "value", "_cherri_optional_result_v1", true, argument))
		g.caller()
		result, _ := p15DecodeOptionalGraph(g, g.call(g.payload("accept")), "has_value", "value")
		consume(result)
		g.boundary(g.outer, 2, false)
	case "function_map_later_argument":
		envelope := g.header("accept")
		g.get("arg_0", envelope)
		g.get("arg_1", envelope)
		g.output(g.value("gettext", map[string]any{"WFTextActionText": "DONE"}))
		g.caller()
		g.value("gettext", map[string]any{"WFTextActionText": "SEED"})
		later := g.value("setitemname", map[string]any{"WFName": "LATER"})
		literal := p15S01Carrier(g, p15S01ContainerLiteral)
		field := p15S01ContainerRows(p15S01ContainerRow(key, 0, p15FunctionText("\uFFFC", literal)))
		consume(g.call(g.payload("accept", p15FunctionArgument{true, 1, field}, p15FunctionArgument{true, 0, p15FunctionEdge(later)})))
		g.boundary(g.outer, 2, false)
	case "plain_control":
		consume(p15S01Dictionary(g, p15S01ContainerRow(key, 0, p15FunctionText("ordinary {literal}"))))
	case "raw_native_control":
		g.emit("dictionary", map[string]any{"WFItems": p15S01ContainerRows(p15S01ContainerRow("key", 0, p15S01ContainerLiteral))})
	}
	// Every source in this table falls through in authored main, after any
	// dispatcher has closed. This exact action is distinct from function output.
	g.emit("nothing", nil)
	if err := p15M02MainVoidBoundaryError(actions); err != nil {
		return err
	}
	if err := p15S01CompleteGraph(g); err != nil {
		return err
	}
	if name != "raw_native_control" {
		for _, action := range actions {
			if err := p15S01CompletePlaceholderCoverage(action); err != nil {
				return err
			}
		}
	}
	return nil
}

func p15S01ContainerGraphCases() []string {
	return []string{"map_immutable", "map_mutable", "literal_key_sort", "nested_array", "list_dictionary", "nested_later_call", "computed_key_later_call", "function_scalar", "function_map_later_argument", "registered_map", "optional_scalar_argument", "optional_map_argument", "optional_scalar_return", "optional_map_return", "plain_control", "raw_native_control"}
}

func TestP15S01ContainerCarriersPreserveCompleteGraphs(t *testing.T) {
	for _, name := range p15S01ContainerGraphCases() {
		t.Run(name, func(t *testing.T) {
			actions := p15CompiledActions(t, p15S01ContainerSource(name))
			if err := p15S01ContainerGraphError(actions, name); err != nil {
				if os.MkdirAll("dist/p15-s01-container", 0700) == nil {
					if raw, e := json.MarshalIndent(actions, "", "  "); e == nil {
						_ = os.WriteFile("dist/p15-s01-container/"+name+".json", raw, 0600)
					}
				}
				t.Fatal(err)
			}
		})
	}
}

// Change a single actual consumer, not an expected graph or production helper.
func p15S01ChangeFirst(value any, change func(map[string]any) bool) bool {
	switch item := value.(type) {
	case map[string]any:
		if change(item) {
			return true
		}
		for _, child := range item {
			if p15S01ChangeFirst(child, change) {
				return true
			}
		}
	case []any:
		for _, child := range item {
			if p15S01ChangeFirst(child, change) {
				return true
			}
		}
	}
	return false
}

func TestP15S01ContainerGraphsRejectCausalMutations(t *testing.T) {
	for _, name := range p15S01ContainerGraphCases() {
		if name == "plain_control" || name == "raw_native_control" {
			continue
		}
		t.Run(name, func(t *testing.T) {
			original := p15CompiledActions(t, p15S01ContainerSource(name))
			if err := p15S01ContainerGraphError(original, name); err != nil {
				t.Fatal("healthy actual graph", err)
			}
			carrierIndex := -1
			for index, action := range original {
				literal, _ := p15Param(action)["WFTextActionText"].(string)
				if strings.ContainsRune(literal, '\uFFFC') && p15Param(action)["CustomOutputName"] == "Text" {
					carrierIndex = index
					break
				}
			}
			if carrierIndex < 0 {
				t.Fatal("actual literal producer absent")
			}
			for _, fault := range []string{"literal_bytes", "producer_kind", "producer_uuid", "producer_name", "consumer_uuid", "consumer_name", "missing_range", "wrong_range", "unbound_character", "helper_reordered", "extra_action", "duplicate_producer"} {
				t.Run(fault, func(t *testing.T) {
					var actions []map[string]any
					raw, err := json.Marshal(original)
					if err != nil {
						t.Fatal(err)
					}
					if err = json.Unmarshal(raw, &actions); err != nil {
						t.Fatal(err)
					}
					if err := p15S01ContainerGraphError(actions, name); err != nil {
						t.Fatal("unchanged clone", err)
					}
					params := p15Param(actions[carrierIndex])
					id := params["UUID"]
					changed := true
					switch fault {
					case "literal_bytes":
						params["WFTextActionText"] = strings.ReplaceAll(params["WFTextActionText"].(string), "\uFFFC", "")
					case "producer_kind":
						actions[carrierIndex]["WFWorkflowActionIdentifier"] = "is.workflow.actions.number"
					case "producer_uuid":
						delete(params, "UUID")
					case "producer_name":
						params["CustomOutputName"] = "Wrong"
					case "consumer_uuid", "consumer_name":
						changed = false
						for _, action := range actions {
							if p15S01ChangeFirst(action, func(item map[string]any) bool {
								if item["Type"] != "ActionOutput" || item["OutputUUID"] != id {
									return false
								}
								if fault == "consumer_uuid" {
									item["OutputUUID"] = "MISSING_LITERAL_PRODUCER"
								} else {
									item["OutputName"] = "Wrong"
								}
								return true
							}) {
								changed = true
								break
							}
						}
					case "missing_range", "wrong_range", "unbound_character":
						changed = false
						for _, action := range actions {
							if p15S01ChangeFirst(action, func(item map[string]any) bool {
								if item["WFSerializationType"] != "WFTextTokenString" {
									return false
								}
								body, _ := item["Value"].(map[string]any)
								ranges, _ := body["attachmentsByRange"].(map[string]any)
								for key, raw := range ranges {
									ref, _ := raw.(map[string]any)
									if ref["OutputUUID"] != id {
										continue
									}
									if fault == "unbound_character" {
										body["string"] = "\uFFFC" + body["string"].(string)
									} else {
										delete(ranges, key)
										if fault == "wrong_range" {
											ranges["{999, 1}"] = raw
										}
									}
									return true
								}
								return false
							}) {
								changed = true
								break
							}
						}
					case "helper_reordered":
						actions[carrierIndex], actions[carrierIndex+1] = actions[carrierIndex+1], actions[carrierIndex]
					case "extra_action":
						actions = append(actions, map[string]any{"WFWorkflowActionIdentifier": "is.workflow.actions.setclipboard"})
					case "duplicate_producer":
						actions = append(actions, actions[carrierIndex])
					}
					if !changed {
						t.Fatal("causal mutation did not change the emitted graph")
					}
					if err := p15S01ContainerGraphError(actions, name); err == nil {
						t.Fatal("accepted corrupted actual graph", fault)
					}
				})
			}
		})
	}
}

// Corrupt the actual main boundary while retaining every literal/function edge.
// In particular, a Nothing inside an Optional decoder cannot satisfy main.
func TestP15S01ContainerMainBoundaryRejectsCausalMutations(t *testing.T) {
	for _, name := range p15S01ContainerGraphCases() {
		t.Run(name, func(t *testing.T) {
			original := p15CompiledActions(t, p15S01ContainerSource(name))
			if err := p15S01ContainerGraphError(original, name); err != nil {
				t.Fatal("healthy complete graph", err)
			}
			for _, fault := range []string{"missing_clear", "clear_input", "clear_identity", "extra_envelope", "clear_before_consumer"} {
				t.Run(fault, func(t *testing.T) {
					broken := p15C01Clone(t, original)
					last := len(broken) - 1
					switch fault {
					case "missing_clear":
						broken = broken[:last]
					case "clear_input":
						broken[last]["WFWorkflowActionParameters"] = map[string]any{"WFInput": "LEAK"}
					case "clear_identity":
						broken[last]["WFWorkflowActionParameters"] = map[string]any{"UUID": "INVENTED_MAIN_OUTPUT"}
					case "extra_envelope":
						broken[last]["PublicUnexpected"] = "changed"
					case "clear_before_consumer":
						broken[last], broken[last-1] = broken[last-1], broken[last]
					}
					if err := p15S01ContainerGraphError(broken, name); err == nil {
						t.Fatal("accepted changed main boundary", fault)
					}
				})
			}
		})
	}
}
